# -*- coding: utf-8 -*-
"""向 QC 台账 LEDGER.md 追加条目（幂等）。

⚠️ 历史台账可能归档在 `_archive/qc-working/.qc/LEDGER.md`。
   本脚本用 `qc_input` 语义解析：**优先库根 `.qc/`，缺失则回退归档**；
   首次追加会把归档台账**复制**到库根 `.qc/`（归档层只进不出，绝不原地改写）。
   全新空库没有归档台账时，首次追加直接在库根 `.qc/` 新建。

用法:
    python tools/qc_ledger.py --file <含正文的文本文件> [--key "<幂等判据>"]
    python tools/qc_ledger.py --text "<正文>" [--key "<幂等判据>"]
    python tools/qc_ledger.py --selftest

"""
import sys, os, shutil, argparse


ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import qc_input, qc_work_dir  # noqa: E402
from kb_lib import console_encoding
console_encoding()


def ledger_path(create=False):
    """台账路径：库根 `.qc/LEDGER.md` 优先，缺失时从归档**复制**过来。

    绝不在 `_archive/` 内原地写入（归档层只进不出）。
    """
    new = os.path.join(qc_work_dir(create=create), "LEDGER.md")
    if os.path.exists(new):
        return new
    arch = qc_input("LEDGER.md")
    if os.path.exists(arch) and os.path.abspath(arch) != os.path.abspath(new):
        if not create:
            # 干跑/只读：直接用归档件，不产生副本
            return arch
        os.makedirs(os.path.dirname(new), exist_ok=True)
        shutil.copyfile(arch, new)
        print("已从归档复制台账 -> %s（归档原件未改动）" % new)
    return new


def append(body, key=None, create=True):
    """返回值：("exists"|"appended", key)。"""
    p = ledger_path(create=create)
    t = open(p, encoding="utf-8").read() if os.path.exists(p) else ""
    key = key or body.strip().split("\n")[0][:40]
    if key and key in t:
        return "exists", key
    if not create:
        return "dry", key
    open(p, "w", encoding="utf-8", newline="\n").write(
        t.rstrip() + "\n" + body.rstrip() + "\n")
    return "appended", key


def selftest():
    """校验器自检：合成夹具（正例 + 反例），不断言任何具体库的台账现状。"""
    import tempfile
    ok = True
    saved_env = os.environ.get("MATSCI_QC_DIR")
    with tempfile.TemporaryDirectory() as td:
        qdir = os.path.join(td, ".qc")
        os.makedirs(qdir)
        lp = os.path.join(qdir, "LEDGER.md")
        with open(lp, "w", encoding="utf-8") as f:
            f.write("# quality-check 台账\n\n## 既有批次\n- 条目\n")
        os.environ["MATSCI_QC_DIR"] = qdir
        try:
            # 正例：幂等判据——已在台账中的 key 必须报 exists，且**不**写盘
            before = os.path.getmtime(lp)
            status, _ = append("## probe\n- x", key="quality-check", create=False)
            after = os.path.getmtime(lp)
            got = status == "exists" and before == after
            print(f"  [{'ok' if got else 'FAIL'}] 正例 幂等判据命中即跳过、未写盘（mtime 未变）")
            ok = ok and got
            # 反例：绝不存在的 key 在 create=False 下必须报 dry（**不写盘**）
            status, _ = append("## probe2\n- y", key="绝不存在的-key-xyz-123", create=False)
            got = status == "dry"
            print(f"  [{'ok' if got else 'FAIL'}] 反例 干跑不写盘 -> {status}")
            ok = ok and got
            # 正例：create=True 真追加，且写后内容含新条目（空库首追加也走这条路）
            status, _ = append("## probe3\n- z", key="probe3-新条目", create=True)
            got = (status == "appended"
                   and "## probe3" in open(lp, encoding="utf-8").read())
            print(f"  [{'ok' if got else 'FAIL'}] 正例 追加落盘且可复读 -> {status}")
            ok = ok and got
        finally:
            if saved_env is None:
                os.environ.pop("MATSCI_QC_DIR", None)
            else:
                os.environ["MATSCI_QC_DIR"] = saved_env
    # 正例：写盘目标在库根、未落归档
    wd = qc_work_dir(create=True)
    safe = "_archive" not in wd.replace("/", "\\")
    print(f"  [{'ok' if safe else 'FAIL'}] 写盘目标在库根、未落归档 -> {wd}")
    ok = ok and safe
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="向 QC 台账追加条目（幂等）")
    ap.add_argument("--file")
    ap.add_argument("--text")
    ap.add_argument("--key", default=None,
                    help="幂等判据；若 LEDGER 中已含该串则跳过")
    ap.add_argument("--dry-run", action="store_true", help="只判定，不写盘")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()

    if a.selftest:
        return selftest()

    if a.file:
        body = open(a.file, encoding="utf-8").read()
    elif a.text:
        body = a.text
    else:
        ap.print_help()
        print("\n需要 --file 或 --text")
        return 1

    status, key = append(body, a.key, create=not a.dry_run)
    if status == "exists":
        print("已存在，跳过: %s" % key)
    elif status == "dry":
        print("干跑：将追加（key=%s）——未写盘" % key)
    else:
        print("已追加（key=%s）" % key)
    return 0


if __name__ == "__main__":
    sys.exit(main())
